import { isCommitAttributionSideEffectPath, isIgnorableTaskScopedDirtySideEffect, isRuntimeCommitSideEffect, resolveGitExecutable, shouldStageGovernedGitHeadEvidenceBeforeCommit, } from './git-process-port.js';
import { inspectAutoGeneratedResidue, } from "../../framework-development.js";
import { gitHeadEvidencePath, } from "../../git-head-evidence.js";
import { readResolutionAuthorizedForeignTaskIds } from "../../broker-conflict-resolution.js";
import { sealCommitBundleFromLiveIndex } from "./sealed-commit-attribution.js";
import { ATM_INDEX_FOREIGN_ACTIVE_STAGED, authorizeGitIndexOverrideLease, buildForeignActiveStagedDiagnostic, inspectGitIndexOwnership, } from "../../git-index-ownership.js";
import { normalizeRelativePath, normalizeTaskClaimIntent, pathMatchesTaskScope, uniqueSorted, } from "../commit-scope-policy.js";
import { buildTaskScopedCommitFileSet, } from "../commit-bundle-filter.js";
import { isActionableManualResidue, isDeferrableForeignGovernanceResidue, } from "../governance-residue-policy.js";
import { ATM_PROTECTED_GOVERNANCE_STATE_DESTRUCTIVE_WRITE, inspectProtectedGovernanceStateDestructiveChanges, } from "../protected-governance-state.js";
import { buildCopyableGitCommitCommand, buildProtectedForeignStagedOwnershipFiles, buildUnexpectedStagedTasksForGitCommit, deferForeignStagedFiles, isActiveForeignGovernanceResidueOwner, isAllowedGovernanceArtifactPath, isFileAllowedInTaskBundle, readStagedDiffNames, readStagedFiles, stageTaskScopedBundleFiles } from './git-index-transaction.js';
import { parseTaskClaim } from './identity-check-command.js';
import { cleanupAutoGeneratedResidue, isIgnorableCommitStagingSideEffect, listTaskScopedWorktreeDirtyFiles, resolveTaskDeclaredScope } from './task-scope-staging.js';
export function resolveTaskScopedCommitBundle(input) {
    const declaredScope = resolveTaskDeclaredScope(input.cwd, input.taskId, input.taskDocument);
    const gitExecutable = resolveGitExecutable();
    const copyableCommitCommand = buildCopyableGitCommitCommand({
        cwd: input.cwd,
        message: input.message,
        trailers: input.trailers,
    });
    let stagedFiles = readStagedFiles(input.cwd);
    let gitIndexOwnership = inspectGitIndexOwnership({
        cwd: input.cwd,
        taskId: input.taskId,
        stagedFiles,
    });
    const indexLeaseAuthorization = input.deferForeignStaged &&
        gitIndexOwnership.foreignActiveStaged.length > 0
        ? authorizeGitIndexOverrideLease({
            cwd: input.cwd,
            leaseId: input.stageOverrideLease ?? null,
            actorId: input.actorId ?? "",
            taskId: input.taskId,
            report: gitIndexOwnership,
        })
        : null;
    const hasAuthorizedIndexLease = indexLeaseAuthorization?.ok === true;
    let unexpectedStagedTasks = buildUnexpectedStagedTasksForGitCommit(input.cwd, input.taskId, declaredScope, stagedFiles);
    let protectedForeignStagedOwnershipFiles = buildProtectedForeignStagedOwnershipFiles(unexpectedStagedTasks);
    const resolutionAuthorizedForeignTaskIds = readResolutionAuthorizedForeignTaskIds(input.cwd, input.brokerConflictResolutionPath ?? null, input.taskId);
    const protectedForeignDeferAuthorized = unexpectedStagedTasks.length > 0 &&
        unexpectedStagedTasks.every((entry) => resolutionAuthorizedForeignTaskIds.has(entry.taskId.toUpperCase()));
    let deferredForeignStagedSnapshot = null;
    let deferredForeignStagedFiles = [];
    if (input.deferForeignStaged &&
        unexpectedStagedTasks.length > 0 &&
        input.apply &&
        !hasAuthorizedIndexLease &&
        (protectedForeignStagedOwnershipFiles.length === 0 ||
            protectedForeignDeferAuthorized)) {
        deferredForeignStagedFiles = uniqueSorted(unexpectedStagedTasks.flatMap((entry) => entry.stagedFiles));
        deferredForeignStagedSnapshot = deferForeignStagedFiles(input.cwd, input.taskId, unexpectedStagedTasks);
        stagedFiles = readStagedFiles(input.cwd);
        gitIndexOwnership = inspectGitIndexOwnership({
            cwd: input.cwd,
            taskId: input.taskId,
            stagedFiles,
        });
        unexpectedStagedTasks = buildUnexpectedStagedTasksForGitCommit(input.cwd, input.taskId, declaredScope, stagedFiles);
        protectedForeignStagedOwnershipFiles =
            buildProtectedForeignStagedOwnershipFiles(unexpectedStagedTasks);
    }
    const dirtyFiles = listTaskScopedWorktreeDirtyFiles(input.cwd);
    const activeDeferredSnapshot = normalizeRelativePath(deferredForeignStagedSnapshot ?? "");
    const residueCandidateFiles = dirtyFiles.filter((filePath) => normalizeRelativePath(filePath) !== activeDeferredSnapshot &&
        !isIgnorableTaskScopedDirtySideEffect(filePath));
    const residueReport = inspectAutoGeneratedResidue(input.taskId, residueCandidateFiles, input.cwd);
    const autoCleanedResidue = input.apply
        ? cleanupAutoGeneratedResidue(input.cwd, residueReport.autoCleanSafe)
        : [];
    const deferredForeignStagedSet = new Set(deferredForeignStagedFiles.map(normalizeRelativePath));
    const blockedResidue = residueReport.blockAndExplain.filter((entry) => !deferredForeignStagedSet.has(normalizeRelativePath(entry.path)) &&
        !(input.deferForeignStaged &&
            isDeferrableForeignGovernanceResidue(input.taskId, entry)) &&
        !isActiveForeignGovernanceResidueOwner(input.cwd, input.taskId, entry));
    const manualReviewResidue = residueReport.manualReview.filter((entry) => isActionableManualResidue(entry.path) &&
        !(input.deferForeignStaged &&
            isDeferrableForeignGovernanceResidue(input.taskId, entry)) &&
        !isActiveForeignGovernanceResidueOwner(input.cwd, input.taskId, entry));
    const effectiveDirtyFiles = autoCleanedResidue.length > 0
        ? listTaskScopedWorktreeDirtyFiles(input.cwd)
        : dirtyFiles;
    const stagedSet = new Set(stagedFiles);
    const unstagedDirtyFiles = effectiveDirtyFiles.filter((filePath) => !stagedSet.has(filePath));
    const inScopeUnstagedDirty = unstagedDirtyFiles.filter((filePath) => !isRuntimeCommitSideEffect(filePath) &&
        (isCommitAttributionSideEffectPath(filePath) ||
            declaredScope.some((scope) => pathMatchesTaskScope(filePath, scope)) ||
            isAllowedGovernanceArtifactPath(input.cwd, filePath, input.taskId)));
    const skippedExternalDirtyFiles = unstagedDirtyFiles.filter((filePath) => !isCommitAttributionSideEffectPath(filePath) &&
        !declaredScope.some((scope) => pathMatchesTaskScope(filePath, scope)) &&
        !isIgnorableTaskScopedDirtySideEffect(filePath) &&
        !isIgnorableCommitStagingSideEffect(input.cwd, filePath, input.taskId));
    const inScopeStagedFiles = stagedFiles.filter((filePath) => isFileAllowedInTaskBundle(input.cwd, filePath, input.taskId, declaredScope));
    const outOfScopeStagedFiles = stagedFiles.filter((filePath) => !isFileAllowedInTaskBundle(input.cwd, filePath, input.taskId, declaredScope));
    const inScopeStagedDeletions = readStagedDiffNames(input.cwd, "D").filter((filePath) => isFileAllowedInTaskBundle(input.cwd, filePath, input.taskId, declaredScope));
    const outOfScopeStagedDeletions = readStagedDiffNames(input.cwd, "D").filter((filePath) => !isFileAllowedInTaskBundle(input.cwd, filePath, input.taskId, declaredScope));
    const taskClaim = parseTaskClaim(input.taskDocument.claim);
    const claimIntent = input.taskDocument.claim &&
        typeof input.taskDocument.claim === "object" &&
        !Array.isArray(input.taskDocument.claim)
        ? normalizeTaskClaimIntent(input.taskDocument.claim.intent)
        : "write";
    const source = input.taskDocument.source &&
        typeof input.taskDocument.source === "object" &&
        !Array.isArray(input.taskDocument.source)
        ? input.taskDocument.source
        : {};
    const planningPath = typeof source.planPath === "string"
        ? normalizeRelativePath(source.planPath)
        : "";
    const protectedGovernanceStateReport = inspectProtectedGovernanceStateDestructiveChanges({
        cwd: input.cwd,
        taskId: input.taskId,
    });
    const governanceBundleWarnings = [];
    const commitAttributionStageCandidates = unstagedDirtyFiles.filter((filePath) => isCommitAttributionSideEffectPath(filePath));
    const stageCandidates = uniqueSorted([
        ...commitAttributionStageCandidates,
        ...(input.autoStage
            ? inScopeUnstagedDirty.filter((filePath) => !isCommitAttributionSideEffectPath(filePath))
            : []),
    ]);
    const commitFiles = buildTaskScopedCommitFileSet({
        inScopeStagedFiles,
        inScopeStagedDeletions,
        stageCandidates,
        uniqueSorted,
    });
    const commitFilesWithGovernanceEvidence = shouldStageGovernedGitHeadEvidenceBeforeCommit(commitFiles)
        ? uniqueSorted([...commitFiles, gitHeadEvidencePath])
        : commitFiles;
    const closeoutOnlyMutationFiles = claimIntent === "closeout-only"
        ? uniqueSorted(commitFiles.filter((filePath) => {
            const normalized = normalizeRelativePath(filePath);
            if (!normalized || normalized.startsWith(".atm/"))
                return false;
            if (planningPath && normalized === planningPath)
                return false;
            if (isCommitAttributionSideEffectPath(normalized))
                return false;
            return declaredScope.some((scope) => pathMatchesTaskScope(normalized, scope));
        }))
        : [];
    let blockedCode = null;
    let blockedSummary = null;
    if (!protectedGovernanceStateReport.ok) {
        blockedCode = ATM_PROTECTED_GOVERNANCE_STATE_DESTRUCTIVE_WRITE;
        blockedSummary = protectedGovernanceStateReport.summary;
    }
    else if (input.deferForeignStaged &&
        gitIndexOwnership.foreignActiveStaged.length > 0 &&
        !protectedForeignDeferAuthorized &&
        !hasAuthorizedIndexLease) {
        const diagnostic = buildForeignActiveStagedDiagnostic(gitIndexOwnership);
        blockedCode = ATM_INDEX_FOREIGN_ACTIVE_STAGED;
        blockedSummary = indexLeaseAuthorization && !indexLeaseAuthorization.ok
            ? indexLeaseAuthorization.summary
            : `Refusing to unstage/defer foreign-active staged files owned by ${diagnostic.ownerTaskIds.join(", ")}: ${diagnostic.stagedPaths.join(", ")}. Wait for the owner, request a Broker index lane, or use an explicit stage-override lease with human approval.`;
    }
    else if (input.deferForeignStaged &&
        protectedForeignStagedOwnershipFiles.length > 0 &&
        !protectedForeignDeferAuthorized &&
        !hasAuthorizedIndexLease) {
        blockedCode = "ATM_GIT_COMMIT_PROTECTED_FOREIGN_STAGED_OWNERSHIP";
        blockedSummary = `Refusing to unstage protected .atm/history files that belong to another task: ${protectedForeignStagedOwnershipFiles.join(", ")}. Wait for that task owner to commit/release, request a Broker index lane, or use an explicit stage-override lease with human approval.`;
    }
    else if (blockedResidue.length > 0) {
        blockedCode = "ATM_GIT_COMMIT_GENERATED_RESIDUE_BLOCKED";
        blockedSummary = `Generated residue belongs to another task/run and must be cleared explicitly: ${blockedResidue.map((entry) => entry.path).join(", ")}`;
    }
    else if (manualReviewResidue.length > 0) {
        blockedCode = "ATM_GIT_COMMIT_GENERATED_RESIDUE_MANUAL_REVIEW";
        blockedSummary = `Generated-looking residue needs manual review before commit: ${manualReviewResidue.map((entry) => entry.path).join(", ")}`;
    }
    else if (taskClaim?.state === "active" &&
        closeoutOnlyMutationFiles.length > 0) {
        blockedCode = "ATM_GIT_COMMIT_CLOSEOUT_ONLY_MUTATION";
        blockedSummary = `Task ${input.taskId} holds a closeout-only claim but the commit bundle contains source mutations: ${closeoutOnlyMutationFiles.join(", ")}. Re-claim with --claim-intent write before committing new source changes.`;
    }
    if (!blockedCode && input.apply && stageCandidates.length > 0) {
        stageTaskScopedBundleFiles(input.cwd, stageCandidates, process.env);
        stagedFiles = readStagedFiles(input.cwd);
        gitIndexOwnership = inspectGitIndexOwnership({
            cwd: input.cwd,
            taskId: input.taskId,
            stagedFiles,
        });
    }
    if (unexpectedStagedTasks.length > 0) {
        governanceBundleWarnings.push(`Foreign staged tasks remain in the shared index but will be excluded from the governed commit bundle: ${unexpectedStagedTasks.map((entry) => entry.taskId).join(", ")}`);
    }
    if (autoCleanedResidue.length > 0) {
        governanceBundleWarnings.push(`ATM auto-cleaned generated residue before governed commit: ${autoCleanedResidue.map((entry) => `${entry.path} (${entry.reason})`).join("; ")}`);
    }
    const deferredGovernanceResidue = residueReport.blockAndExplain.filter((entry) => input.deferForeignStaged &&
        isDeferrableForeignGovernanceResidue(input.taskId, entry));
    if (deferredGovernanceResidue.length > 0) {
        governanceBundleWarnings.push(`Deferred foreign generated governance residue outside this task bundle: ${deferredGovernanceResidue.map((entry) => `${entry.path} (${entry.ownerTaskId})`).join("; ")}`);
    }
    return {
        schemaId: "atm.taskScopedCommitBundle.v1",
        taskId: input.taskId,
        ok: blockedCode === null,
        // TASK-GIT-0029: seal the admitted content here, where ownership was just
        // inspected. The commit executor assembles from this seal, so a concurrent
        // writer replacing content behind an admitted path afterwards cannot ride
        // along under an already-approved path.
        sealedBundle: sealCommitBundleFromLiveIndex({
            cwd: input.cwd,
            paths: commitFilesWithGovernanceEvidence,
            provenance: "task-scope",
        }),
        apply: input.apply,
        stagingStrategy: input.autoStage
            ? "explicit-pathspec-git-add"
            : "manual-staged-index",
        stagingCommand: input.autoStage && stageCandidates.length > 0
            ? ["git", "add", "-A", "-f", "--", ...stageCandidates]
            : null,
        stageFiles: input.apply && input.autoStage ? stageCandidates : inScopeUnstagedDirty,
        commitFiles: commitFilesWithGovernanceEvidence,
        skippedExternalDirtyFiles: uniqueSorted(skippedExternalDirtyFiles),
        unexpectedStagedTasks,
        gitIndexOwnership,
        indexLeaseAuthorization,
        outOfScopeStagedFiles: uniqueSorted([
            ...outOfScopeStagedFiles,
            ...outOfScopeStagedDeletions,
        ]),
        governanceBundleWarnings,
        protectedGovernanceStateReport,
        blockedCode,
        blockedSummary,
        closeoutOnlyMutationFiles,
        gitExecutable,
        copyableCommitCommand,
        deferredForeignStagedSnapshot,
        autoCleanedResidue,
        blockedResidue,
        manualReviewResidue,
    };
}
